public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    // Use the event's own formatted message if available.
    // Most logging frameworks provide this method.
    // If not, fall back to the raw message and parameters.
    try {
        String formatted = event.getFormattedMessage();
        if (formatted != null) {
            return formatted;
        }
    } catch (Throwable t) {
        // ignore and fall back
    }
    // Fallback: use raw message and format with its parameters
    Object[] params = event.getParameters();
    String raw = event.getMessage();
    if (raw == null) {
        raw = "";
    }
    if (params != null && params.length > 0) {
        try {
            return java.text.MessageFormat.format(raw, params);
        } catch (Exception e) {
            // ignore failures and return raw
        }
    }
    return raw;
}

