        return event.getMessage().getFormattedMessage();
    } catch (Throwable t) {
        // Fallback if getFormattedMessage is not available
        return event.toString();
    }
}

public String format(LoggingEvent event){
    if(event == null){
        return "";
    }
    StringBuilder sb = new StringBuilder();
    // timestamp
    sb.append(String.format("%1$tF %1$tT.%1$tL", new Date(event.getTimeStamp())));
    // thread name
    sb.append(" [").append(event.getThreadName()).append("] ");
    // log level
    sb.append(event.getLevel()).append(" ");
    // logger name
    sb.append(event.getLoggerName()).append(" - ");
    // message
    String message = event.getMessage() != null ? event.getMessage().getFormattedMessage() : "";
    sb.append(message);
    // throwable, if any
    if(event.getThrowableInformation() != null){
        Throwable t = event.getThrowableInformation().getThrowable();
        sb.append(" : ").append(t.toString());
        for(StackTraceElement ste : t.getStackTrace()){
            sb.append("\n\tat ").append(ste.toString());
        }
    }
    return sb.toString();
}

public String format(LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    String pat = this.pattern;
    for (int i = 0; i < pat.length(); i++) {
        char c = pat.charAt(i);
        if (c == '%' && i + 1 < pat.length()) {
            char next = pat.charAt(i + 1);
            switch (next) {
                case 'm':
                    sb.append(event.getRenderedMessage());
                    i++;
                    break;
                case 'p':
                    sb.append(event.getLevel().toString());
                    i++;
                    break;
                case 't':
                    sb.append(event.getThreadName());
                    i++;
                    break;
                case 'd':
                    sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                            .format(new java.util.Date(event.getTimeStamp())));
                    i++;
                    break;
                case 'c':
                    sb.append(event.getLoggerName());
                    i++;
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    i++;
                    break;
                case '%':
                    sb.append('%');
                    i++;
                    break;
                default:
                    sb.append(next);
                    i++;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

