public long contentLength() {
    // Safe guard if the request reference is not available
    if (request == null) {
        return -1;
    }

    // First, try to read the Content‑Length header directly
    String header = request.getHeader("Content-Length");
    if (header != null) {
        try {
            return Long.parseLong(header.trim());
        } catch (NumberFormatException ignored) {
            // header contained non‑numeric data – fall back to other methods
        }
    }

    // Fallback to servlet API methods
    int len = request.getContentLength();
    if (len >= 0) {
        return len;
    }

    // Since Java 7, getContentLengthLong() returns a long
    try {
        return request.getContentLengthLong();
    } catch (Exception ignored) {
        // Method not available or execution failed
    }

    // If all else fails, we cannot determine the length
    return -1;
}

