    // does not support a direct API, or if the length is not specified,
    // a negative value is returned.
    if (request == null) {
        return -1L;
    }
    try {
        // Servlet 3.1 and newer
        return request.getContentLengthLong();
    } catch (NoSuchMethodError | UnsupportedOperationException e) {
        // Servlet 2.5 / older
        return (long) request.getContentLength();
    } catch (Exception e) {
        // Fallback if any unexpected exception occurs
        return -1L;
    }
}

