private int parseEndOfLine(String headerPart,int end){
    int len = headerPart.length();
    for (int i = Math.max(0, end); i < len - 1; i++){
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    // Find the next CRLF sequence starting after the last processed byte.
    // Return the index of the carriage return (\r) that begins the CRLF.
    int crlf = headerPart.indexOf("\r\n", end + 1);
    return crlf;
}

private int parseEndOfLine(String headerPart,int end){
    int len = headerPart.length();
    int pos = end + 1;
    while (pos < len - 1) {
        if (headerPart.charAt(pos) == '\r' && headerPart.charAt(pos + 1) == '\n') {
            return pos;
        }
        pos++;
    }
    return -1; // not found
}

private int parseEndOfLine(String headerPart, int end) {
    int index = headerPart.indexOf("\r\n", end);
    if (index == -1) {
        throw new IllegalArgumentException("End of line not found in header part");
    }
    return index;
}

private int parseEndOfLine(String headerPart,int end) {
    int len = headerPart.length();
    // Search for CRLF starting from 'end'
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // Fallback: search for LF if CRLF not found
    for (int i = end; i < len; i++) {
        if (headerPart.charAt(i) == '\n') {
            return i;
        }
    }
    // No line terminator found
    return -1;
}

