public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File f = stack.pop();
        if (f.isDirectory()) {
            File[] children = f.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
        f.deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        java.util.Stack<File> stack = new java.util.Stack<>();
        stack.push(file);
        while (!stack.isEmpty()) {
            File f = stack.pop();
            if (f.isDirectory()) {
                File[] children = f.listFiles();
                if (children != null) {
                    for (File child : children) {
                        stack.push(child);
                    }
                }
            }
            f.delete();
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        throw new FileNotFoundException("File not found: " + file);
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            java.nio.file.Path path = file.toPath();
            java.nio.file.Files.walkFileTree(path, new java.nio.file.SimpleFileVisitor<java.nio.file.Path>() {
                @Override
                public java.nio.file.FileVisitResult visitFile(java.nio.file.Path file, java.nio.file.attribute.BasicFileAttributes attrs) throws java.io.IOException {
                    java.nio.file.Files.delete(file);
                    return java.nio.file.FileVisitResult.CONTINUE;
                }

                @Override
                public java.nio.file.FileVisitResult postVisitDirectory(java.nio.file.Path dir, IOException exc) throws IOException {
                    java.nio.file.Files.delete(dir);
                    return java.nio.file.FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            System.err.println("Unable to delete " + file + " on JVM exit: " + e.getMessage());
        }
    }));
}

public static void forceDeleteOnExit(final File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("The file must not be null");
    }

    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursive(file);
        } catch (IOException e) {
            // Deletion failed during JVM shutdown; log or rethrow as unchecked if desired
            e.printStackTrace();
        }
    }));
}

private static void deleteRecursive(File file) throws IOException {
    if (!file.exists()) {
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursive(child);
            }
        }
    }
    if (!file.delete()) {
        throw new IOException("Unable to delete " + file);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (!file.exists()) {
        return; // nothing to schedule
    }
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File f = stack.pop();
        f.deleteOnExit();
        if (f.isDirectory()) {
            File[] children = f.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
    }
}

