@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Separate vertices into two partitions based on key naming convention.
    // For this example we assume keys starting with "left" belong to the left partition
    // and keys starting with "right" belong to the right partition.
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();

    // Add all vertices to the graph and classify them.
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        target.addVertex(vertex);

        String key = entry.getKey().toLowerCase();
        if (key.startsWith("left")) {
            left.add(vertex);
        } else if (key.startsWith("right")) {
            right.add(vertex);
        } // else leave unclassified; no edges will be created for it
    }

    // Create edges to form a complete bipartite graph between left and right sets.
    for (V lVertex : left) {
        for (V rVertex : right) {
            // Graph.addEdge may return null if the edge already exists; that's fine.
            target.addEdge(lVertex, rVertex);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if(target == null || resultMap == null){
        return;
    }
    // Define sizes of the two partitions (you can modify these as needed)
    final int leftSize = 3;
    final int rightSize = 3;
    // Lists to keep track of vertices for easy edge generation
    List<V> leftVertices = new ArrayList<>();
    List<V> rightVertices = new ArrayList<>();

    @SuppressWarnings("unchecked")
    V vertex;
    // Create left partition vertices
    for(int i = 0; i < leftSize; i++){
        vertex = (V) ("L" + i);
        target.addVertex(vertex);
        leftVertices.add(vertex);
        resultMap.put("L" + i, vertex);
    }
    // Create right partition vertices
    for(int i = 0; i < rightSize; i++){
        vertex = (V) ("R" + i);
        target.addVertex(vertex);
        rightVertices.add(vertex);
        resultMap.put("R" + i, vertex);
    }
    // Add edges between every pair of left and right vertices (complete bipartite)
    for(V u : leftVertices){
        for(V v : rightVertices){
            target.addEdge(u, v);
        }
    }
}

