public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message, buffer);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(cos, message);
    cos.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message, buffer);
    byte[] lenBuf = new byte[5];
    int lenPos = 0;
    int v = size;
    while (v >= 0x80) {
        lenBuf[lenPos++] = (byte)(v | 0x80);
        v >>>= 7;
    }
    lenBuf[lenPos++] = (byte)v;
    out.write(lenBuf, 0, lenPos);
    CodedOutputStream coded = CodedOutputStream.newInstance(out);
    schema.writeTo(message, coded, buffer);
    coded.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the serialized size of the message into the provided buffer
    int size = schema.getSerializedSize(message, buffer);

    // Prepare a CodedOutputStream to write varint length followed by the message
    CodedOutputStream cos = CodedOutputStream.newInstance(out);

    // Write the length prefix as a raw varint
    cos.writeRawVarint32(size);

    // Write the actual message data using the schema, sending it directly to the OutputStream
    // The schema should know how to use the LinkedBuffer for efficient encoding
    schema.writeTo(message, cos, buffer);

    // Flush the CodedOutputStream to ensure all bytes are written to the underlying stream
    cos.flush();

    // Return the size of the serialized message (excluding the length prefix)
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message
    int size = schema.computeSize(message);
    // Create a CodedOutputStream backed by the OutputStream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    // Write the message length as a varint
    codedOut.writeRawVarint32(size);
    // Serialize the message itself
    schema.writeTo(message, codedOut, buffer);
    codedOut.flush();
    return size;
}

