    if (data == null) return;
    // Assume cache is a Map<String, Object> defined in the surrounding class
    data.forEach((k, v) -> cache.merge(k, v, (oldVal, newVal) -> {
        if (oldVal == null) return newVal;
        if (oldVal instanceof Number && newVal instanceof Number) {
            if (oldVal instanceof Integer) return ((Integer) oldVal) + ((Integer) newVal);
            if (oldVal instanceof Long) return ((Long) oldVal) + ((Long) newVal);
            if (oldVal instanceof Double) return ((Double) oldVal) + ((Double) newVal);
            if (oldVal instanceof Float) return ((Float) oldVal) + ((Float) newVal);
            // Fallback to double addition
            return ((Number) oldVal).doubleValue() + ((Number) newVal).doubleValue();
        }
        // Otherwise, concatenate string representations
        return String.valueOf(oldVal) + String.valueOf(newVal);
    }));
}

