public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping of the index from the cluster
    Mappings current = getCurrentMapping(tableName);
    if (current == null) {
        return new Mappings();
    }

    // Sources of the current and history mapping
    Map<String, Object> currentSource = current.getSource();
    Map<String, Object> historySource = mappings.getSource();

    @SuppressWarnings("unchecked")
    Map<String, Object> currentProps = currentSource.containsKey("properties")
            ? (Map<String, Object>) currentSource.get("properties")
            : Collections.emptyMap();

    @SuppressWarnings("unchecked")
    Map<String, Object> historyProps = historySource.containsKey("properties")
            ? (Map<String, Object>) historySource.get("properties")
            : Collections.emptyMap();

    // Build the diff of properties that are missing in the history mapping
    Map<String, Object> diffProps = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if ("_source".equals(field)) {
            continue; // Skip _source to avoid update conflicts
        }
        if (!historyProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }

    if (diffProps.isEmpty()) {
        return new Mappings(); // No differences
    }

    // Construct the diff mapping preserving other top-level keys from the current mapping
    Map<String, Object> diffSource = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : currentSource.entrySet()) {
        String key = entry.getKey();
        if ("_source".equals(key)) {
            continue; // Skip _source
        }
        if ("properties".equals(key)) {
            diffSource.put(key, diffProps); // Only the new properties
        } else {
            diffSource.put(key, entry.getValue()); // Copy other config like settings; dynamic etc.
        }
    }

    return new Mappings(diffSource);
}

public void addNewTarget(Channels channels,IConsumer consumer){
    if (channels == null) {
        throw new IllegalArgumentException("channels must not be null");
    }
    if (consumer == null) {
        return;
    }
    // If Channels implements java.util.Collection, add the consumer directly
    if (channels instanceof java.util.Collection) {
        @SuppressWarnings("unchecked")
        java.util.Collection<IConsumer> col = (java.util.Collection<IConsumer>) channels;
        col.add(consumer);
        return;
    }
    // Try common add methods via reflection
    try {
        java.lang.reflect.Method addMethod = channels.getClass().getMethod("add", IConsumer.class);
        addMethod.invoke(channels, consumer);
    } catch (NoSuchMethodException e) {
        try {
            java.lang.reflect.Method addTargetMethod = channels.getClass().getMethod("addTarget", IConsumer.class);
            addTargetMethod.invoke(channels, consumer);
        } catch (Exception ex) {
            throw new RuntimeException("Unable to add consumer to Channels", ex);
        }
    } catch (Exception e) {
        throw new RuntimeException("Unable to add consumer to Channels", e);
    }
}

