    String osVersion = System.getProperty("os.version");
    String configPath;

    if (osName != null && osName.startsWith("Windows") && osVersion != null && osVersion.startsWith("5.")) {
        // Windows 2000
        String drive = System.getenv("HOMEDRIVE");
        if (drive == null || drive.isEmpty()) {
            drive = System.getProperty("user.home");
        }
        String docsAndSettings = drive + File.separator + "Documents and Settings";
        configPath = docsAndSettings + File.separator + "lf5";
    } else {
        // Other platforms
        String userHome = System.getProperty("user.home");
        if (userHome == null || userHome.isEmpty()) {
            userHome = ".";
        }
        configPath = userHome + File.separator + "lf5";
    }

    File configDir = new File(configPath);
    if (!configDir.exists()) {
        configDir.mkdirs();
    }
}

