public synchronized void send(final String message) {
    String msg = message;
    // Ensure telnet-friendly CRLF line ending
    if (!msg.endsWith("\r\n")) {
        if (msg.endsWith("\n")) {
            msg = msg.substring(0, msg.length() - 1) + "\r\n";
        } else {
            msg += "\r\n";
        }
    }
    // Iterate over all connected client sockets and send the message
    for (Socket client : clients) {
        try {
            PrintWriter out = new PrintWriter(client.getOutputStream(), true);
            out.print(msg);
            out.flush();
        } catch (IOException e) {
            // Handle broken connection (e.g., remove client from list)
            try {
                client.close();
            } catch (IOException ex) {
                // ignore
            }
            clients.remove(client);
        }
    }
}

