public void put(LoggingEvent o) {
    int pos = nextPutIndex;
    int idx = pos & ringMask;   // ringMask = buffer.length - 1 for power‑of‑two buffers
    buffer[idx] = o;
    nextPutIndex = pos + 1;
}

public void put(LoggingEvent o){
    if (size == capacity) {
        // silently drop
        return;
    }
    buffer[next] = o;
    next = (next + 1) % capacity;
    ++size;
}

public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    // Attempts to insert event into the buffer without blocking.
    // If the buffer is already full, the event is silently dropped.
    if (!buffer.offer(o)) {
        // event is dropped – no action needed
    }
}

public void put(LoggingEvent o){
    // Check if buffer has free space; if full, silently drop the event
    if (count == capacity) {
        // Buffer is full; dropping event silently as per contract
        return;
    }
    buffer[tail] = o;
    tail = (tail + 1) % capacity;
    count++;
}

