public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int end = index + len;
    int bytes = 0;
    int i = index;
    while (i < end) {
        int cp = str.codePointAt(i);
        int cl = Character.charCount(cp);
        // UTF-8 length calculation
        if (cp < 0x80) {
            bytes += 1;
        } else if (cp < 0x800) {
            bytes += 2;
        } else if (cp < 0x10000) {
            bytes += 3;
        } else {
            bytes += 4;
        }
        i += cl;
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        // Check for surrogate pair
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                int codePoint = Character.toCodePoint(ch, low);
                i++; // advance past low surrogate
                if (codePoint <= 0x7FF) {
                    size += 2;
                } else if (codePoint <= 0xFFFF) {
                    size += 3;
                } else {
                    size += 4;
                }
                continue;
            }
        }
        // Single char case
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = 0;
    int end = index + len;
    if (len <= 0) {
        return 0;
    }
    for (; i < len; ) {
        char ch = str.charAt(index + i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && (i + 1) < len
                && Character.isLowSurrogate(str.charAt(index + i + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(index + i + 1));
            i += 2;
        } else {
            codePoint = ch;
            i += 1;
        }

        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            // values above U+FFFF are 4 bytes in UTF‑8
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int byteCount = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char c = str.charAt(i);
        if (c < 0x80) {                  // 1-byte ASCII
            byteCount += 1;
        } else if (c < 0x800) {          // 2-byte
            byteCount += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < end && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                // Valid surrogate pair -> 4-byte UTF-8
                byteCount += 4;
                i++; // Skip the low surrogate
            } else {
                // Unpaired surrogate; encode as replacement character (3 bytes)
                byteCount += 3;
            }
        } else {                         // 3-byte
            byteCount += 3;
        }
        i++;
    }
    return byteCount;
}

