private Set<V> initVisibleVertices(){
    // Create a set to hold vertices that appear in at least one edge
    Set<V> visibleVertices = new HashSet<>();
    // Iterate over all edges and add both endpoints to the set
    for (Edge<V> edge : edges) {
        V v1 = edge.getSrc();
        V v2 = edge.getDst();
        if (v1 != null) {
            visibleVertices.add(v1);
        }
        if (v2 != null) {
            visibleVertices.add(v2);
        }
    }
    // Return the set of vertices with a positive degree
    return visibleVertices;
}

