public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1);
    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1; // ignore leading slash
    }
    for (int i = start; i < parts.length; i++) {
        String seg = parts[i];
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // keep the segment as is if decoding fails
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present; it is not a delimiter for a path segment
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return segments;
    }
    String[] parts = rawPath.split("/", -1); // keep trailing empty segments
    for (String rawPart : parts) {
        String decodedPart;
        if (decode) {
            try {
                decodedPart = java.net.URLDecoder.decode(rawPart, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                decodedPart = rawPart; // fall back to raw if decoding fails
            }
        } else {
            decodedPart = rawPart;
        }
        segments.add(new PathSegmentImpl(rawPart, decodedPart));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath(); // keep percent-encoding
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    int pos = 0;
    if (rawPath.charAt(0) == '/') {
        pos = 1; // ignore leading '/'
    }
    while (pos < rawPath.length()) {
        int nextSlash = rawPath.indexOf('/', pos);
        String part;
        if (nextSlash == -1) {
            part = rawPath.substring(pos);
            pos = rawPath.length();
        } else {
            part = rawPath.substring(pos, nextSlash);
            pos = nextSlash + 1;
        }
        if (part.isEmpty()) {
            continue; // skip empty segments
        }
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; fallback to raw part
                seg = part;
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

