    if (cp == null || cp.isEmpty()) {
        return new File[0];
    }
    String[] segments = cp.split(File.pathSeparator);
    File[] files = new File[segments.length];
    for (int i = 0; i < segments.length; i++) {
        files[i] = new File(segments[i]);
    }
    return files;
}

