public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double x = box.getX();
    double y = box.getY();
    double width = box.getWidth();
    double height = box.getHeight();
    double halfWidth = width / 2.0;
    Box2D leftBox = new Box2D(x, y, halfWidth, height);
    Box2D rightBox = new Box2D(x + halfWidth, y, halfWidth, height);
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double midX = (box.getMinX() + box.getMaxX()) / 2.0;
    Box2D left = new Box2D(box.getMinX(), box.getMinY(), midX, box.getMaxY());
    Box2D right = new Box2D(midX, box.getMinY(), box.getMaxX(), box.getMaxY());
    return new Pair<>(left, right);
}

