private void enlarge(final int size){
    int minCapacity = pos + size;
    if (minCapacity > array.length) {
        int oldLength = array.length;
        int newCapacity = Math.max(oldLength << 1, minCapacity);
        byte[] newArray = new byte[newCapacity];
        System.arraycopy(array, 0, newArray, 0, oldLength);
        array = newArray;
    }
}

private void enlarge(final int size) {
    int requiredLength = this.size + size;
    if (requiredLength <= buffer.length) {
        return;
    }
    int newCapacity = Math.max(buffer.length * 2, requiredLength);
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    buffer = newBuffer;
}

private void enlarge(final int size){
    int newSize = pos + size;
    if (newSize > buf.length){
        byte[] newbuf = new byte[Math.max(buf.length << 1, newSize)];
        System.arraycopy(buf, 0, newbuf, 0, pos);
        buf = newbuf;
    }
}

private void enlarge(final int size) {
    int oldCapacity = bytes.length;
    int newCapacity = Math.max(oldCapacity + size, oldCapacity * 2);
    byte[] newBytes = new byte[newCapacity];
    System.arraycopy(bytes, 0, newBytes, 0, oldCapacity);
    bytes = newBytes;
}

private void enlarge(final int size){
    if (size <= 0) return;
    int newCapacity = Math.max(buf.length << 1, buf.length + size);
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, buf.length);
    buf = newBuf;
}

