public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    if (name.length() > 1 &&
        Character.isUpperCase(name.charAt(0)) &&
        Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    return name.substring(0, 1).toUpperCase() + name.substring(1);
}

