public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        if (cur.buf != null && cur.pos > 0) {
            out.write(cur.buf, 0, cur.pos);
            total += cur.pos;
        }
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        int len = cur.count;
        out.write(cur.buf, 0, len);
        totalSize += len;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        out.write(current.buf, 0, current.pos);
        totalSize += current.pos;
        current = current.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int start = current.start;      // starting position of valid data in this node
        int end   = current.end;        // ending position (non‑inclusive) in this node
        int length = end - start;
        if (length > 0) {
            out.write(current.buf, start, length); // write the valid bytes
            totalSize += length;
        }
        current = current.next; // move to the next node in the linked list
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the portion of the buffer that contains data
        out.write(node.buf, 0, node.cursor);
        totalSize += node.cursor;
        node = node.next;
    }
    return totalSize;
}

