    sb.append("[");
    Node<?> current = front; // assumes a field named 'front' pointing to the first node
    while (current != null) {
        sb.append(current.data); // assumes the node holds its value in a field named 'data'
        if (current.next != null) sb.append(", ");
        current = current.next;
    }
    sb.append("]");
    return sb.toString();
}

