public String format(final LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    long timeStamp = event.getTimeStamp();
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    sb.append(sdf.format(new java.util.Date(timeStamp)));
    sb.append('[').append(event.getLevel()).append("] ");
    sb.append(event.getLoggerName()).append(" - ");
    sb.append(event.getMessage());
    Throwable t = event.getThrowable();
    if(t != null){
        sb.append(System.lineSeparator());
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        t.printStackTrace(pw);
        sb.append(sw.toString());
    }
    return sb.toString();
}

public String format(final LoggingEvent event){
    if(event == null){
        return "";
    }
    StringBuilder sb = new StringBuilder();
    // Timestamp
    sb.append(new java.util.Date(event.getTimeStamp()).toString());
    // Thread name
    sb.append(" [").append(event.getThreadName()).append("] ");
    // Log level
    sb.append(event.getLevel()).append(" ");
    // Logger name
    sb.append(event.getLoggerName()).append(" - ");
    // Formatted message
    sb.append(event.getFormattedMessage());
    // Throwable if present
    if(event.getThrowableProxy() != null){
        sb.append(System.lineSeparator());
        sb.append(event.getThrowableProxy().getClassName()).append(": ").append(event.getThrowableProxy().getMessage());
    }
    return sb.toString();
}

public String format(final LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    java.util.Date date = new java.util.Date(event.getTimeStamp());
    sb.append("[")
      .append(sdf.format(date))
      .append("] ")
      .append("[")
      .append(event.getThreadName())
      .append("] ")
      .append("[")
      .append(event.getLevel())
      .append("] ")
      .append(event.getLoggerName())
      .append(": ");
    Object msgObj = event.getMessage();
    String message = (msgObj != null) ? msgObj.toString() : "null";
    sb.append(message);
    if(event.getThrowableInformation() != null){
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        event.getThrowableInformation().getThrowable().printStackTrace(pw);
        pw.flush();
        sb.append("\n").append(sw.toString());
    }
    return sb.toString();
}

public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    StringBuilder sb = new StringBuilder();

    // Timestamp
    long timestamp = event.getTimeStamp();
    sb.append('[').append(timestamp).append("] ");

    // Log level
    sb.append('[').append(event.getLevel()).append("] ");

    // Thread name
    sb.append('[').append(event.getThreadName()).append("] ");

    // Logger name
    sb.append('[').append(event.getLoggerName()).append("] - ");

    // Message
    String formattedMessage = event.getFormattedMessage();
    sb.append(formattedMessage == null ? "null" : formattedMessage);

    // Throwable (if present)
    if (event.getThrowableInformation() != null) {
        Throwable[] throwableReps = event.getThrowableInformation().getThrowableStrRep();
        if (throwableReps != null && throwableReps.length > 0) {
            sb.append(System.lineSeparator()).append(throwableReps[0]);
        }
    }

    return sb.toString();
}

public String format(final LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
    sb.append(" [").append(event.getLevel()).append("] ");
    sb.append("(").append(event.getThreadName()).append(") ");
    sb.append(event.getLoggerName()).append(" - ");
    sb.append(event.getMessage() != null ? event.getMessage().toString() : "null");
    String[] throwable = event.getThrowableStrRep();
    if (throwable != null && throwable.length > 0){
        sb.append(System.lineSeparator());
        for (String line : throwable){
            sb.append(line).append(System.lineSeparator());
        }
    }
    sb.append(System.lineSeparator());
    return sb.toString();
}

public static double[] toPrimitive(final Double[] array){
    if (array == null){
        return null;
    }
    double[] result = new double[array.length];
    for (int i = 0; i < array.length; i++){
        if (array[i] == null){
            throw new NullPointerException("Array element at index " + i + " is null");
        }
        result[i] = array[i];
    }
    return result;
}

