    if (array == null) {
        return null;
    }
    double[] primitiveArray = new double[array.length];
    for (int i = 0; i < array.length; i++) {
        Double boxed = array[i];
        if (boxed == null) {
            throw new NullPointerException("array[" + i + "] is null");
        }
        primitiveArray[i] = boxed;
    }
    return primitiveArray;
}

