            case 7: // ITEM_Object
                stackMapTableEntries.putU2(vt.constantPoolIndex);
                break;
            case 8: // ITEM_Uninitialized
                stackMapTableEntries.putU2(vt.uninitializedOffset);
                break;
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        int tag = type.getTag();
        stackMapTableEntries.putByte(tag);
        switch (tag) {
            case AbstractType.OBJECT:
                stackMapTableEntries.putUshort(type.getPoolIndex());
                break;
            case AbstractType.UNINITIALIZED:
                stackMapTableEntries.putUshort(type.getOffset());
                break;
            default:
                // TOP, INTEGER, FLOAT, LONG, DOUBLE, NULL, UNINITIALIZED_THIS need no extra data
                break;
        }
    }
}

