@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Fail fast for unsupported target types
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException(
            "Target type is not java.lang.Character: " + type.getName());
    }

    // Null values stay null
    if (value == null) {
        return null;
    }

    // Direct Character or primitive char (boxed)
    if (value instanceof Character) {
        return value;
    }

    // String: accept only single‑character strings
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new Exception(
                "Cannot convert String to Character: String length must be 1, was " + str.length()
            );
        }
        return str.charAt(0);
    }

    // Number: cast to char using the integer value
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    // Boolean: represent as 't' / 'f'
    if (value instanceof Boolean) {
        return (char) (((Boolean) value) ? 1 : 0);
    }

    // Fallback: attempt string conversion
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    // If none of the above, throw an exception
    throw new Exception(
        "Conversion failed for value: " + value + " (type " + value.getClass().getName() + ")"
    );
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }

    if (value == null) {
        return null;
    }

    // Already a Character instance
    if (value instanceof Character) {
        return value;
    }

    // String of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length must be 1, got \"" + str + "\"");
        }
    }

    // Number: convert numeric value to char code
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }

    // Unsupported source type
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return Character.valueOf(cs.charAt(0));
        }
        throw new Exception("Cannot convert CharSequence to Character: length is not 1");
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return Character.valueOf((char) intValue);
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Target type is not Character");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() != 1) {
            throw new IllegalArgumentException("String length must be 1 to convert to Character");
        }
        return Character.valueOf(s.charAt(0));
    }
    if (value instanceof java.lang.CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() != 1) {
            throw new IllegalArgumentException("CharSequence length must be 1");
        }
        return Character.valueOf(cs.charAt(0));
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    throw new IllegalArgumentException("Cannot convert to Character: " + value.getClass().getName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }

    // Only apply conversion when the target type is java.lang.Character or char
    if (type != Character.class && type != char.class) {
        return value;
    }

    // If the value is already a Character, just return it
    if (value instanceof Character) {
        return value;
    }

    // If the value is a CharSequence (e.g., String), use the first character
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return java.lang.Character.valueOf(cs.charAt(0));
        } else {
            throw new IllegalArgumentException(
                String.format("Cannot convert CharSequence '%s' to a single Character.", cs));
        }
    }

    // If the value is a Number, cast its integer value to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return java.lang.Character.valueOf((char) intVal);
    }

    // For any other type, attempt to use its string representation if it's length 1
    String str = value.toString();
    if (str.length() == 1) {
        return java.lang.Character.valueOf(str.charAt(0));
    }

    throw new IllegalArgumentException(
        String.format("Cannot convert value of type %s (%s) to java.lang.Character.", 
                      value.getClass().getName(), value));
}

