public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    if (desiredCapacity <= 3) return 3;
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) candidate++;   // make it odd
    while (true) {
        int limit = (int)Math.sqrt(candidate);
        boolean isPrime = true;
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) return candidate;
        candidate += 2;   // check next odd number
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if (n % 2 == 0) n++;  // start with odd number
    int max = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        // within 11% of desiredCapacity
        max = desiredCapacity + desiredCapacity / 9; // 100% + 11% ≈ 111%
    }
    for (;;) {
        if (isPrime(n)) {
            return n <= max ? n : n; // always return the prime once found
        }
        n += 2; // skip even numbers
    }
}

private static final boolean isPrime(int n){
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5, w = 2; i * i <= n; i += w, w = 6 - w) {
        if (n % i == 0) return false;
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int n = desiredCapacity;
    if (n % 2 == 0) {
        n++; // start with an odd number
    }
    int upperLimit = n;
    if (desiredCapacity >= 1000) {
        // limit within 11% of desiredCapacity
        double max = desiredCapacity * 1.11;
        upperLimit = (int) max + 1;
        if (upperLimit % 2 == 0) {
            upperLimit++; // make upper limit odd for parity consistency
        }
    }
    for (; ; n += 2) { // check only odd numbers
        if (isPrime(n)) {
            return n;
        }
        if (desiredCapacity >= 1000 && n > upperLimit) {
            // If no prime was found within the 11% window, keep searching.
            // The specification guarantees that a prime will be found fairly close.
            // We simply continue to search beyond the limit if necessary.
        }
    }

    // Helper method to test primality
    boolean isPrime(int num) {
