public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd (except 2).  
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        // Check divisibility by 3 to  sqrt(candidate), stepping by 2 (only odd divisors)
        int sqrt = (int) Math.sqrt(candidate);
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // next odd candidate
    }
}

