    java.util.Properties props = new java.util.Properties();
    java.nio.file.Path configFile = java.nio.file.Paths.get("config.properties");
    if (java.nio.file.Files.exists(configFile)) {
        try (java.io.InputStream in = java.nio.file.Files.newInputStream(configFile)) {
            props.load(in);
        } catch (java.io.IOException e) {
            java.util.logging.Logger.getLogger(this.getClass().getName()).warning(
                "Failed to load config.properties: " + e.getMessage());
        }
    } else {
        java.util.logging.Logger.getLogger(this.getClass().getName()).info(
            "config.properties not found, using defaults.");
    }

    String distPathStr = props.getProperty("dist.path", "dist");
    java.io.File distDir = new java.io.File(distPathStr);
    if (!distDir.exists()) {
        if (!distDir.mkdirs()) {
            throw new java.lang.RuntimeException(
                "Cannot create distribution directory: " + distDir.getAbsolutePath());
        }
    } else if (!distDir.isDirectory()) {
        throw new java.lang.RuntimeException(
            "Path is not a directory: " + distDir.getAbsolutePath());
    }
