    if (set1 == null || set2 == null || set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<>();
    }

    // Choose the smaller set to iterate over for better performance
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() <= set2.size() ? set2 : set1;

    // Result set to store the intersection
    Set<V> result = new HashSet<>(smaller.size());

    // Add elements that exist in both sets
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }

    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    Set<V> result = new HashSet<>();
    if (set1.size() <= set2.size()) {
        for (V v : set1) {
            if (set2.contains(v)) {
                result.add(v);
            }
        }
    } else {
        for (V v : set2) {
            if (set1.contains(v)) {
                result.add(v);
            }
        }
    }
    return result;
}

