private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    for (KeyStringValuePair kv : properties) {
        if (kv == null || kv.getKey() == null) {
            continue;
        }
        // If the value is null, Gson will store it as JSON null
        json.addProperty(kv.getKey(), kv.getValue());
    }
    return json;
}

private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject json = new JsonObject();
    if (properties == null || properties.isEmpty()) {
        return json;
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        String key = pair.getKey();
        if (key == null || key.isEmpty()) {
            continue;
        }
        // If value is null, we skip adding it or put null string
        String value = pair.getValue();
        if (value != null) {
            json.addProperty(key, value);
        } else {
            json.add(key, JsonNull.INSTANCE);
        }
    }
    return json;
}

