protected int removeUnusedNodes() {
    int removedCount = 0;
    // Assume the roots of the tree are stored in a List<Category> named "roots"
    Iterator<Category> rootIt = roots.iterator();
    while (rootIt.hasNext()) {
        Category root = rootIt.next();
        if (root.isInactive()) {
            removedCount += removeSubtree(root);
            rootIt.remove(); // remove the root from the list
        } else {
            removedCount += pruneInactiveChildren(root);
        }
    }
    return removedCount;
}

private int removeSubtree(Category node) {
    int count = 1; // count the node itself
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += removeSubtree(child);
        }
        children.clear(); // detach all children
    }
    return count;
}

private int pruneInactiveChildren(Category parent) {
    int count = 0;
    Iterator<Category> childIt = parent.getChildren().iterator();
    while (childIt.hasNext()) {
        Category child = childIt.next();
        if (child.isInactive()) {
            count += removeSubtree(child);
            childIt.remove(); // remove the inactive child from the list
        } else {
            count += pruneInactiveChildren(child);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    Iterator<Category> it = categories.iterator();
    while (it.hasNext()) {
        Category cat = it.next();
        if (!cat.isActive()) {
            removedCount += countSubTree(cat);
            it.remove();
        } else {
            removedCount += removeFromNode(cat);
        }
    }
    return removedCount;
}

private int removeFromNode(Category node) {
    if (node.getChildren() == null) {
        return 0;
    }
    Iterator<Category> it = node.getChildren().iterator();
    int count = 0;
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            count += countSubTree(child);
            it.remove();
        } else {
            count += removeFromNode(child);
        }
    }
    return count;
}

private int countSubTree(Category node) {
    int count = 1;
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += countSubTree(child);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    int removed = 0;
    for (int i = children.size() - 1; i >= 0; i--) {
        Category child = children.get(i);
        if (!child.isActive()) {
            children.remove(i);
            removed++;
        } else {
            removed += child.removeUnusedNodes();
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    if (rootCategory == null) {
        return removedCount;
    }

    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(rootCategory);

    while (!stack.isEmpty()) {
        Category current = stack.pop();

        // Use a copy of the child list to safely modify while iterating
        java.util.List<Category> childrenCopy = new java.util.ArrayList<>(current.getChildren());

        for (Category child : childrenCopy) {
            if (!child.isActive()) {
                current.removeChild(child);
                removedCount++;
            } else {
                stack.push(child);
            }
        }
    }

    return removedCount;
}

