final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // constantPoolEntryIndex is the byte offset of the CONSTANT_Utf8 entry (tag byte is at this offset)
    final int len = ((classFileBuffer[constantPoolEntryIndex + 1] & 0xFF) << 8)
                  |  (classFileBuffer[constantPoolEntryIndex + 2] & 0xFF);
    try{
        return new String(classFileBuffer, constantPoolEntryIndex + 3, len, "UTF-8");
    }catch(Exception e){
        throw new RuntimeException(e);
    }
}

