public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // No operation needed if nothing to put
    if (byteLength <= 0) {
        return this;
    }

    // Ensure the buffer can hold the new bytes
    int newSize = position + byteLength;
    if (newSize > capacity) {
        int newCap = Math.max(capacity * 2, newSize);
        byte[] newBuffer = new byte[newCap];
        System.arraycopy(buffer, 0, newBuffer, 0, capacity);
        buffer = newBuffer;
        capacity = newCap;
    }

    // Copy the bytes or insert null bytes
    if (byteArrayValue == null) {
        for (int i = position; i < newSize; i++) {
            buffer[i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, buffer, position, byteLength);
    }

    position = newSize;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength <= 0) {
        return this;
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be >= 0");
    }
    ensureCapacity(length + byteLength);
    if (byteArrayValue == null) {
        java.util.Arrays.fill(array, length, length + byteLength, (byte)0);
    } else {
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds source array length");
        }
        System.arraycopy(byteArrayValue, byteOffset, array, length, byteLength);
    }
    length += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength == 0) return this;
    int newCount = count + byteLength;
    if (newCount > string.length) {
        int newSize = newCount + newCount / 2;
        byte[] newString = new byte[newSize];
        System.arraycopy(string, 0, newString, 0, count);
        string = newString;
    }
    if (byteArrayValue == null) {
        for (int i = count; i < newCount; i++) {
            string[i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, string, count, byteLength);
    }
    count = newCount;
