}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Ensure we have enough capacity
    int neededLength = this.length + byteLength;
    if (needCapacity(neededLength)) {
        int newCap = Math.max(value.length * 2, neededLength);
        byte[] newBytes = new byte[newCap];
        System.arraycopy(this.value, 0, newBytes, 0, this.length);
        this.value = newBytes;
    }

    int destPos = this.length;
    if (byteArrayValue == null) {
        // Fill with zeros
        for (int i = 0; i < byteLength; i++) {
            this.value[destPos + i] = 0;
        }
    } else {
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset/byteLength out of bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, this.value, destPos, byteLength);
    }

    this.length = neededLength;
    return this;
}

private boolean needCapacity(int newLength) {
    return this.value == null || newLength > this.value.length;
}

