    if (!matcher.matches()) {
        return null;
    }

    // Collect named parameters from the pattern (if any)
    Map<String, String> params = new LinkedHashMap<>();
    for (int i = 1; i <= matcher.groupCount(); i++) {
        // Assume paramNames is an array that maps group indices to names
        String name = this.paramNames != null && i-1 < this.paramNames.length
                ? this.paramNames[i-1]
                : "group" + i;
        params.put(name, matcher.group(i));
    }

    // Construct and return a MatchResult (assumes such a constructor exists)
    return new MatchResult(uri.toString(), params);
}

