public final MatchResult match(CharSequence uri){
    if (uri == null) {
        return null;
    }
    String uriStr = uri.toString();
    // Normalize by removing leading/trailing slashes
    String normalizedUri = uriStr.startsWith("/") ? uriStr.substring(1) : uriStr;
    if (normalizedUri.endsWith("/") && normalizedUri.length() > 1) {
        normalizedUri = normalizedUri.substring(0, normalizedUri.length() - 1);
    }
    String normalizedPattern = this.pattern.startsWith("/") ? this.pattern.substring(1) : this.pattern;
    if (normalizedPattern.endsWith("/") && normalizedPattern.length() > 1) {
        normalizedPattern = normalizedPattern.substring(0, normalizedPattern.length() - 1);
    }
    String[] uriParts = normalizedUri.split("/");
    String[] patternParts = normalizedPattern.split("/");
    if (uriParts.length != patternParts.length) {
        return null;
    }
    java.util.Map<String, Object> map = new java.util.LinkedHashMap<>();
    for (int i = 0; i < patternParts.length; i++) {
        String p = patternParts[i];
        String u = uriParts[i];
        if (p.startsWith("{") && p.endsWith("}")) {
            String name = p.substring(1, p.length() - 1).trim();
            if (name.isEmpty()) {
                return null;
            }
            map.put(name, u);
        } else if (!p.equals(u)) {
            return null;
        }
    }
    return new MatchResult(map);
}

