protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour==null||tour.isEmpty()){
        return null;
    }
    // compute degree of each vertex in the tour
    Map<V,Integer> degree = new java.util.HashMap<>();
    for(E e: tour){
        V u=graph.getEdgeSource(e);
        V v=graph.getEdgeTarget(e);
        degree.merge(u,1,Integer::sum);
        degree.merge(v,1,Integer::sum);
    }
    // find a starting vertex (degree==1) if exists, otherwise pick arbitrary
    V start=null;
    for(Map.Entry<V,Integer> entry: degree.entrySet()){
        if(entry.getValue()==1){
            start=entry.getKey();
            break;
        }
    }
    if(start==null){
        E first= tour.iterator().next();
        start=graph.getEdgeSource(first);
    }
    java.util.List<V> vertices = new java.util.ArrayList<>();
    java.util.List<E> edges = new java.util.ArrayList<>();
    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    V current=start;
    vertices.add(current);
    while(!remaining.isEmpty()){
        E chosen=null;
        for(E e: remaining){
            V u=graph.getEdgeSource(e);
            V v=graph.getEdgeTarget(e);
            if(u.equals(current)||v.equals(current)){
                chosen=e;
                break;
            }
        }
        if(chosen==null){
            throw new IllegalArgumentException("Tour edges do not form a continuous path");
        }
        edges.add(chosen);
        V next = graph.getEdgeSource(chosen).equals(current)? graph.getEdgeTarget(chosen): graph.getEdgeSource(chosen);
        vertices.add(next);
        current=next;
        remaining.remove(chosen);
    }
    double weight=0.0;
    for(E e: edges){
        weight+=graph.getEdgeWeight(e);
    }
    return new org.jgrapht.GraphWalk<>(graph,start,current,vertices,edges,weight);
}

