        return false;
    }
    // Detach the node from its previous neighbor
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // node was the head
        head = node.next;
    }
    // Detach the node from its next neighbor
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node was the tail
        tail = node.prev;
    }
    // Help GC
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

