    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.prev();
    ListNodeImpl<E> next = node.next();

    if (prev == null) { // node is the first element
        first = next;
    } else {
        prev.setNext(next);
    }

    if (next == null) { // node is the last element
        last = prev;
    } else {
        next.setPrev(prev);
    }

