public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    for (Profile profile : currentProfiles) {
        ranges.add(new SequenceRange(profile.getStart(), profile.getEnd()));
    }
    return ranges;
}

public List<SequenceRange> buildSequenceRanges() {
    // obtain the current set of profiles from the stored snapshot
    List<Profile> currentProfiles = this.currentProfilesSnapshot; // field defined elsewhere
    if (currentProfiles == null || currentProfiles.isEmpty()) {
        return Collections.emptyList();
    }
    // sort profiles by their start index to simplify range merging
    currentProfiles.sort(Comparator.comparingLong(Profile::getStart));
    List<SequenceRange> ranges = new ArrayList<>();
    long rangeStart = currentProfiles.get(0).getStart();
    long rangeEnd   = currentProfiles.get(0).getEnd();
    for (int i = 1; i < currentProfiles.size(); i++) {
        Profile p = currentProfiles.get(i);
        // if the next profile overlaps or touches the current range, extend it
        if (p.getStart() <= rangeEnd + 1) {
            rangeEnd = Math.max(rangeEnd, p.getEnd());
        } else {
            // otherwise, finalize the previous range and start a new one
            ranges.add(new SequenceRange(rangeStart, rangeEnd));
            rangeStart = p.getStart();
            rangeEnd   = p.getEnd();
        }
    }
    // add the last range
    ranges.add(new SequenceRange(rangeStart, rangeEnd));
    return ranges;
}

public List<SequenceRange> buildSequenceRanges(){
    ProfilesSegment current = getCurrentProfilesSegment();
    if(current == null){
        return Collections.emptyList();
    }
    List<Integer> sequences = current.getSnapshots()
        .stream()
        .map(Snapshot::getSearchSequence)
        .sorted()
        .distinct()
        .collect(Collectors.toList());
    List<SequenceRange> ranges = new ArrayList<>();
    if(sequences.isEmpty()){
        return ranges;
    }
    int start = sequences.get(0);
    int prev = start;
    for(int i = 1; i < sequences.size(); i++){
        int cur = sequences.get(i);
        if(cur == prev + 1){
            prev = cur;
        }else{
            ranges.add(new SequenceRange(start, prev));
            start = cur;
            prev = cur;
        }
    }
    ranges.add(new SequenceRange(start, prev));
    return ranges;
}

