    List<SequenceRange> ranges = new ArrayList<>();
    for (ProfileSegment seg : segments) {
        ranges.add(new SequenceRange(seg.getStartSequence(), seg.getEndSequence()));
    }
    ranges.sort(Comparator.comparingLong(SequenceRange::getStart));
    return ranges;
}

