public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int lastDot = path.lastIndexOf('.');
    int lastSep = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // No dot or dot is part of directories, no extension to strip
    if (lastDot <= lastSep) {
        return path;
    }
    // Dot is the first character of the filename (hidden file without extension)
    if (lastDot == lastSep + 1) {
        return path;
    }
    return path.substring(0, lastDot);
}

