private String parseToken(final char[] terminators){
    // Assume the scanner has a buffer and a current position field named 'pos'
    // and the length of valid input stored in 'limit'.
    int start = pos;
    while (pos < limit) {
        char c = buffer[pos];
        // Check if the current character is a terminator
        boolean isTerminator = false;
        for (char t : terminators) {
            if (c == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;  // stop before the terminator
        }
        pos++; // advance to next character
    }
    // Return the token and leave the position pointing at the terminator or end
    return new String(buffer, start, pos - start);
}

