                for (char t : terminators) {
                    if (c == t) {
                        terminatorFound = true;
                        break;
                    }
                }
                if (terminatorFound) {
                    break;
                }
            }
            sb.append((char) c);
        }
    } catch (Exception e) {
        // In case of IO errors just return what has been collected so far
    }
    return sb.toString();
}

