private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    int chInt;
    while ((chInt = reader.read()) != -1) {
        char ch = (char) chInt;
        boolean isTerminator = false;
        for (char t : terminators) {
            if (ch == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            // unread the terminator so it can be processed by subsequent parsing
            reader.unread(chInt);
