private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long cur = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        cur += bounds.get(i);
        suffix.add(0, (int) cur);
    }
    return new Pair<>(suffix, cur);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = (bounds == null) ? 0 : bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    for (int i = 0; i < n; i++) suffixSum.add(0);
    long sum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.set(i, (int) sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long total = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        total += bounds.get(i);
        suffix.add(0, (int) total);
    }
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    long totalSum = 0;
    long running = 0;
    int[] suffixArr = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        running += val;
        suffixArr[i] = (int) running;
        totalSum += val;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int v : suffixArr) {
        suffix.add(v);
    }
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if(bounds == null || bounds.isEmpty()){
        return Pair.of(new ArrayList<Integer>(), 0L);
    }
    int size = bounds.size();
    int[] suffixArr = new int[size];
    long totalSum = 0L;
    for(int i = size - 1; i >= 0; i--){
        totalSum += bounds.get(i);
        suffixArr[i] = (int)totalSum;
    }
    List<Integer> suffixList = new ArrayList<Integer>(size);
    for(int i = 0; i < size; i++){
        suffixList.add(suffixArr[i]);
    }
    return Pair.of(suffixList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

