private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.size == 0) {
        return;
    }
    // Append all nodes from `list` to this list
    if (size == 0) {
        head = list.head;
        tail = list.tail;
    } else {
        tail.next = list.head;
        list.head.prev = tail;
        tail = list.tail;
    }
    size += list.size;
    // De‑initialize the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Continue until the source list has no more nodes
    while (list != null && !list.isEmpty()) {
        // Grab the first node from the source list
        ListNodeImpl<E> node = list.getFirst();

        // Remove it from the source list and add it to this list
        list.removeListNode(node);
        this.addListNode(node);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this || list.isEmpty()) {
        return;
    }

    // Nodes of the source list that will be transferred
    ListNodeImpl<E> first = list.head.next;
    ListNodeImpl<E> last = list.tail.prev;

    // Append the source nodes to the end of this list
    this.tail.prev.next = first;
    first.prev = this.tail.prev;
    this.tail.prev = last;
    last.next = this.tail;

    // Update sizes
    this.size += list.size;
    list.size = 0;

    // Reset the source list to empty
    list.head.next = list.tail;
    list.tail.prev = list.head;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this || list.head == null) {
        return;
    }
    // Lock both lists to ensure the operation is atomic and prevent contention
    synchronized (this) {
        synchronized (list) {
            // Store source nodes
            ListNode<E> first = list.head;
            ListNode<E> last  = list.tail;

            // If this list is empty, just adopt the entire source list
            if (this.tail == null) {
                this.head = first;
            } else {
                // Link the source to the end of this list
                this.tail.next = first;
                first.prev = this.tail;
            }

            // Update tail of this list
            this.tail = last;
            if (last != null) {
                last.next = null;
            }

            // Clear the source list
            list.head = null;
            list.tail = null;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Nothing to move if the source is this list or is empty
    if (list == this || list.size == 0) {
        return;
    }

    // Detach all nodes from the source list
    ListNode<E> sourceHead = list.head;
    ListNode<E> sourceTail = list.tail;
    int movedSize = list.size;

    list.head = null;
    list.tail = null;
    list.size = 0;
    // Ensure the nodes being moved are properly linked
    sourceTail.next = null;

    // Attach the source nodes to this list
    if (this.head == null) {           // Current list is empty
        this.head = sourceHead;
        this.tail = sourceTail;
        sourceHead.prev = null;
    } else {                           // Append after current tail
        this.tail.next = sourceHead;
        sourceHead.prev = this.tail;
        this.tail = sourceTail;
        this.tail.next = null;
    }

    // Update the size of this list
    this.size += movedSize;
}

