public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    for (Object keyObj : map.keySet()) {
        if (!(keyObj instanceof String)) {
            continue;
        }
        String key = (String) keyObj;
        // Only consider properties that can be written to this BeanMap
        if (!this.isWritable(key)) {
            continue;
        }
        // Only read from source if it is readable
        if (!map.isReadable(key)) {
            continue;
        }
        Object value = map.get(key);
        this.put(key, value);
    }
}

public void putAllWriteable(BeanMap map) {
    if (map == null) {
        return;
    }
    for (Object key : map.keySet()) {
        Object value;
        try {
            value = map.get(key);
        } catch (Exception e) {
            // Unable to read from source (possible write‑only property); skip
            continue;
        }
        try {
            this.put(key, value);
        } catch (Exception e) {
            // Destination is read‑only or incompatible; ignore
        }
    }
}

public void putAllWriteable(BeanMap map){
    // Iterate over all properties of the supplied BeanMap
    for (Map.Entry<String, Object> entry : map.entrySet()){
        String name = entry.getKey();
        // Only copy the property if it is writable in the supplied BeanMap
        if (map.isWritable(name)){
            this.put(name, entry.getValue());
        }
    }
}

