private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparators = new ArrayList<>();
    // Iterate over all edges in the graph
    for (E edge : graph.getEdges()) {
        // Retrieve the endpoints of the current edge
        Pair<Integer, Integer> endpoints = graph.getEdgeVertices(edge);
        int u = endpoints.getFirst();
        int v = endpoints.getSecond();

        // Gather the neighbors of both endpoints, excluding the endpoints themselves
        Set<Integer> neighborhood = new HashSet<>(graph.getNeighbors(u));
        neighborhood.addAll(graph.getNeighbors(v));
        neighborhood.remove(u);
        neighborhood.remove(v);

        // Convert to list for index-based subset generation
        List<Integer> verts = new ArrayList<>(neighborhood);
        int n = verts.size();

        // Store separators that successfully separate u and v
        List<List<Pair<Integer,Integer>>> separatingSets = new ArrayList<>();

        // Enumerate all non-empty subsets of the neighborhood
        for (int mask = 1; mask < (1 << n); mask++) {
            Set<Integer> subset = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(verts.get(i));
                }
            }
            // Perform BFS/DFS to check connectivity after removing subset
            if (!areConnectedAfterRemoving(subset, u, v)) {
                // Check minimality: no proper subset separates them
                boolean isMinimal = true;
                for (int k = 1; k < subset.size(); k++) {
                    // Generate all k-element subsets of subset
                    List<Integer> subsetList = new ArrayList<>(subset);
                    for (int subMask = 1; subMask < (1 << subset.size()); subMask++) {
                        if (Integer.bitCount(subMask) != k)
                            continue;
                        Set<Integer> smaller = new HashSet<>();
                        for (int j = 0; j < subset.size(); j++) {
                            if ((subMask & (1 << j)) != 0) {
                                smaller.add(subsetList.get(j));
                            }
                        }
                        if (!areConnectedAfterRemoving(smaller, u, v)) {
                            isMinimal = false;
                            break;
                        }
                    }
                    if (!isMinimal) break;
                }
                if (isMinimal) {
                    // Convert separator set into list of Pair<Integer,Integer> (vertex, 0) representation
                    List<Pair<Integer,Integer>> separator = new ArrayList<>();
                    for (int vert : subset) {
                        separator.add(Pair.of(vert, 0));
                    }
                    separatingSets.add(separator);
                }
            }
        }

        // Append all separators for this edge to the global list
        for (List<Pair<Integer,Integer>> sep : separatingSets) {
            globalSeparators.add(Pair.of(sep, edge));
        }
    }
    return globalSeparators;
}

private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparators = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparators = computeLocalSeparatorList(e);
        globalSeparators.add(new Pair<>(localSeparators, e));
    }
    return globalSeparators;
