private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort(sorted);
    for (K key : keys){
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0){
            idx = -(idx + 1);
        } else {
            // move to the first element that is greater than the key
            while (idx < sorted.size() && sorted.get(idx).compareTo(key) == 0){
                idx++;
            }
        }
        bounds.add(idx);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (K key : keys) {
        int bound;
        if (key instanceof Number) {
            bound = ((Number) key).intValue();
        } else {
            // Fallback to hash code if key is not a Number
            bound = key.hashCode();
        }
        bounds.add(bound);
    }
    return bounds;
}

