public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Determine base directory (directory part of the path). 
    String basePath = path;
    // If path ends with a slash, it is already a directory.
    if (!basePath.endsWith("/")) {
        int lastSlashIndex = basePath.lastIndexOf('/');
        if (lastSlashIndex >= 0) {
            basePath = basePath.substring(0, lastSlashIndex + 1);
        } else {
            basePath = "";
        }
    }
    // Collect the parts of the base path into a stack.
    java.util.Deque<String> parts = new java.util.LinkedList<>();
    if (!basePath.isEmpty()) {
        for (String part : basePath.split("/")) {
            if (!part.isEmpty()) {
                parts.addLast(part);
            }
        }
    }
    // Process each segment of the relative path.
    for (String segment : relativePath.split("/")) {
        if (segment.isEmpty() || segment.equals(".")) {
            continue; // skip empty or current directory '.'.
        }
        if (segment.equals("..")) {
            if (!parts.isEmpty()) {
                parts.removeLast(); // move up one directory.
            }
        } else {
            parts.addLast(segment); // add the new directory/file.
        }
    }
    // Build the resulting path string.
    StringBuilder result = new StringBuilder();
    // Preserve leading slash if the original path was absolute.
    if (path.startsWith("/")) {
        result.append("/");
    }
    java.util.Iterator<String> it = parts.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    return result.toString();
}

