    final boolean absolute = path.startsWith(separator);
    // Initialize a stack for the path components
    Deque<String> stack = new ArrayDeque<>();

    // Split the base path into parts, process each component
    String[] baseParts = path.split(separator, -1);
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
