            stack.addLast(part);               // Add a normal directory/file name
        }
    }

    // Apply the relative path components
    String[] relParts = relativePath.split(separator, -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!absolute) {
                stack.addLast(part);
