        } else {
            stack.addLast(part);
        }
    }

    // Construct the final path string
    StringBuilder result = new StringBuilder();
    if (absolute) {
        result.append(separator);
    }
    Iterator<String> iter = stack.iterator();
    while (iter.hasNext()) {
        result.append(iter.next());
        if (iter.hasNext()) {
            result.append(separator);
        }
    }

    // Edge case: if the result is empty but the original was absolute, return "/"
    if (result.length() == 0 && absolute) {
