    Node from = prevNode.isVirtual() ? prevNode.getRealNode() : prevNode;
    Node to   = curNode.isVirtual()   ? curNode.getRealNode()   : curNode;
    // Return an edge connecting the real nodes
    return new Edge(from, to);
