Edge edgeToNext(){
    // If there are no more nodes, simply return null
    if (nextIndex >= nodes.size()) {
        return null;
    }

    // Retrieve the next node in the sequence
    Node current = nodes.get(nextIndex);

    Edge edge = null;

    // If we have a previously returned node, create the edge
    if (prevNode != null) {
        Node realPrev = isVirtual(prevNode) ? getRealCounterpart(prevNode) : prevNode;
        Node realCurrent = isVirtual(current) ? getRealCounterpart(current) : current;
        edge = new Edge(realPrev, realCurrent);
    }

    // Update state for subsequent calls
    prevNode = current;
    nextIndex++;

    return edge;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen) {
        return false;
    }
    if (subLen == 0) {
        return index <= strLen;
    }
    if (index + subLen > strLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

