}

protected void append(LoggingEvent event) {
    // Get the formatted log message from the event
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }
    // Ensure each message ends with a line separator so clients receive distinct lines
    message += System.lineSeparator();

    // Iterate over each connected client and write the message
    // The clients collection is assumed to be a thread‑safe set or list of objects that expose a Writer
    synchronized (this) {
        Iterator<Client> it = clients.iterator();
        while (it.hasNext()) {
            Client client = it.next();
            try {
                Writer writer = client.getWriter();
                writer.write(message);
                writer.flush();
            } catch (IOException ex) {
                // If writing fails, remove the client from the set and log the error
                it.remove();
                LogLog.error("Unable to write log event to client: " + client, ex);
            }
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) return;
    String msg = event.getRenderedMessage();
    if (msg == null) return;
    byte[] data = (msg + System.lineSeparator()).getBytes();
    synchronized (connectedClients) {
        Iterator<Socket> it = connectedClients.iterator();
        while (it.hasNext()) {
            Socket client = it.next();
            try {
                OutputStream out = client.getOutputStream();
                out.write(data);
                out.flush();
            } catch (IOException e) {
                it.remove();
                try { client.close(); } catch (IOException ignored) {}
            }
        }
    }
}

