private void checkIfPackedField() throws IOException {
    // Determine the wire type and field number from the current tag.
    int tag = this.currentTag;
    int wireType = tag & 0x7;        // last 3 bits
    int fieldNumber = tag >>> 3;     // remaining bits

    // Packed repeated fields use wire type LENGTH_DELIMITED (value 2).
    // If the current tag indicates a length-delimited field and the
    // schema tells us that this field is a repeated primitive type,
    // set the internal flag indicating that packed fields are being
    // read.  The actual schema lookup and field descriptor is
